from __future__ import annotations

import datetime

_MIN_MONTH_NAMES = {
    "JAN": 1, "FEB": 2, "MAR": 3, "APR": 4,
    "MAY": 5, "JUN": 6, "JUL": 7, "AUG": 8,
    "SEP": 9, "OCT": 10, "NOV": 11, "DEC": 12,
}
_MIN_WEEKDAY_NAMES = {
    "SUN": 0, "MON": 1, "TUE": 2, "WED": 3,
    "THU": 4, "FRI": 5, "SAT": 6,
}
_MONTH_NAMES = {v: name for name, v in _MIN_MONTH_NAMES.items()}
_WEEKDAY_NAMES = {v: name for name, v in _MIN_WEEKDAY_NAMES.items()}

_MONTH_MIN, _MONTH_MAX = 1, 12
_DAY_MIN, _DAY_MAX = 1, 31
_WEEKDAY_MIN, _WEEKDAY_MAX = 0, 7


def _split_expression(expression: str) -> list[str]:
    if not isinstance(expression, str):
        raise ValueError("expression must be a string")
    fields = expression.split()
    if len(fields) != 5:
        raise ValueError("expression must have 5 fields")
    return fields


def _is_valid_whitespace(s: str) -> bool:
    return all(ch in " \t\n" for ch in s) or not s


def _parse_number(value: str) -> int:
    if not value:
        raise ValueError("empty number")
    for ch in value:
        if not ch.isdigit():
            raise ValueError("invalid number")
    if len(value) < 1:
        raise ValueError("invalid number")
    return int(value)


def _parse_single_month(value: str) -> int:
    up = value.upper()
    if up in _MONTH_NAMES:
        return _MONTH_NAMES[up]
    if value.isdigit():
        return _parse_number(value)
    raise ValueError(f"invalid month: {value!r}")


def _parse_single_weekday(value: str) -> int:
    up = value.upper()
    if up in _WEEKDAY_NAMES:
        return _WEEKDAY_NAMES[up]
    if value.isdigit():
        return _parse_number(value)
    raise ValueError(f"invalid weekday: {value!r}")


def _days_in_month(year: int, month: int) -> int:
    if year < 1 or year > 9999:
        return 31
    if month == 1:
        return 31
    if month == 2:
        if (year % 4 == 0 and year % 100 != 0) or (year % 400 == 0):
            return 29
        return 28
    if month in (4, 6, 9, 11):
        return 30
    return 31


def _month_is_no_spec(month_field: str) -> bool:
    return month_field == "*"


def _day_or_weekday_is_no_spec(day_field: str) -> bool:
    return day_field == "*"


def _parse_month_field(field: str) -> list[int]:
    field = field.strip()
    if not field:
        raise ValueError("empty field")

    items = field.split(",")
    values: list[int] = []
    for item in items:
        item = item.strip()
        if not item:
            raise ValueError("empty month item")
        if item == "*":
            values.extend(range(_MONTH_MIN, _MONTH_MAX + 1))
        elif item.startswith("*"):
            step = _parse_number(item[1:])
            if step <= 0:
                raise ValueError("step must be positive")
            value = _MONTH_MIN
            while value <= _MONTH_MAX:
                values.append(value)
                value += step
        else:
            if "-" in item:
                left, right = item.split("-", 1)
                if "/" in left or "/" in right:
                    raise ValueError("invalid range step")
                a = _parse_single_month(left)
                b = _parse_single_month(right)
                if a > b:
                    raise ValueError("range endpoints are reversed")
                values.extend(range(a, b + 1))
            elif "/" in item:
                parts = item.split("/")
                if len(parts) != 2:
                    raise ValueError("invalid step syntax")
                left = parts[0]
                step = _parse_number(parts[1])
                if step <= 0:
                    raise ValueError("step must be positive")
                if left == "":
                    value = _MONTH_MIN
                else:
                    value = _parse_single_month(left)
                while value <= _MONTH_MAX:
                    values.append(value)
                    if value >= _MONTH_MAX:
                        break
                    value += step
                    if value > _MONTH_MAX:
                        break
            else:
                values.append(_parse_single_month(item))

    if not values:
        raise ValueError("empty month set")
    if any(v < _MONTH_MIN or v > _MONTH_MAX for v in values):
        raise ValueError("month out of range")
    return sorted(set(values))


def _parse_day_field(field: str) -> list[int] | None:
    if field.strip() == "*":
        return None
    return _parse_month_field(field)


def _parse_weekday_field(field: str) -> list[int] | None:
    if field.strip() == "*":
        return None
    values: list[int] = []
    items = field.split(",")
    for item in items:
        item = item.strip()
        if not item:
            raise ValueError("empty weekday item")
        if item == "*":
            values.extend(range(0, 7))
        elif item.startswith("*"):
            step = _parse_number(item[1:])
            if step <= 0:
                raise ValueError("step must be positive")
            value = 0
            while value <= 6:
                values.append(value)
                value += step
        elif "-" in item:
            left, right = item.split("-", 1)
            if "/" in left or "/" in right:
                raise ValueError("invalid weekday range step")
            a = _parse_single_weekday(left)
            b = _parse_single_weekday(right)
            if a > b:
                # 7 and 0 are equivalent for weekday, but for simple ranges still reject
                # unless explicitly specified as 5-7 style below.
                if not (a == 7 and b == 7):
                    raise ValueError("weekday range is reversed")
            for x in range(a, b + 1):
                if x == 7:
                    x = 0
                if 0 <= x <= 6:
                    values.append(x)
        elif "/" in item:
            parts = item.split("/")
            if len(parts) != 2:
                raise ValueError("invalid weekday step syntax")
            left = parts[0]
            step = _parse_number(parts[1])
            if step <= 0:
                raise ValueError("step must be positive")
            if left == "":
                value = 0
            else:
                value = _parse_single_weekday(left)
            while value <= 6:
                values.append(value)
                value += step
                if value > 6:
                    break
        else:
            values.append(_parse_single_weekday(item))

    if not values:
        raise ValueError("empty weekday set")
    mapped = sorted({(0 if x == 7 else x) for x in values})
    if any(x < 0 or x > 6 for x in mapped):
        raise ValueError("weekday out of range")
    return mapped


def _parse_time_field(month_field: str, day_field: str, weekday_field: str) -> list[tuple[int, int]]:
    minutes = _parse_month_field(month_field)
    hours = _parse_day_field(day_field)
    days_of_week = _parse_weekday_field(weekday_field)
    if hours is None:
        hours = list(range(0, 24))
    if days_of_week is None:
        # No weekday restriction means every weekday is allowed, but this path is only
        # used when the caller already knows a specific weekday constraint exists.
        days_of_week = list(range(0, 7))

    pairs: list[tuple[int, int]] = []
    for day in days_of_week:
        for hour in hours:
            for minute in minutes:
                pairs.append((day, hour, minute))
    return pairs


def _is_month_allowed(month: int, allowed_months: list[int]) -> bool:
    return month in allowed_months


def _day_is_allowed(day: int, month: int, allowed_months: list[int]) -> bool:
    days_in_month = _days_in_month(month, 2026)
    return 1 <= day <= days_in_month and month in allowed_months


def _build_day_allowed_sets_for_years(allowed_months: list[int], max_year: int) -> list[set[int] | None]:
    day_sets: list[set[int] | None] = []
    for year in range(1, max_year + 1):
        month_sets = []
        for month in range(1, 13):
            if month not in allowed_months:
                month_sets.append(set())
            else:
                month_sets.append({
                    day for day in range(1, _days_in_month(year, month) + 1)
                })
        day_sets.append(month_sets)
    return day_sets


def _weekday_allowed_sets(max_year: int) -> list[set[int]]:
    day_sets: list[set[int]] = []
    for year in range(1, max_year + 1):
        day_sets.append({
            (date.weekday())
            for day in range(1, 8)
            for date in [datetime.date(year, 1, 1)]
        })
    # The previous loop is a placeholder; replace with a simple correct implementation.
    day_sets = []
    for year in range(1, max_year + 1):
        for month in range(1, 13):
            for day in range(1, _days_in_month(year, month) + 1):
                d = datetime.date(year, month, day)
                day_sets.append({d.weekday()})
    return day_sets


def _next_run_after_date_on_day(day: datetime.date, allowed_months: list[int], allowed_days: list[int] | None, allowed_weekdays: list[int] | None) -> datetime.datetime | None:
    if _is_month_allowed(day.month, allowed_months):
        if allowed_days is not None and day.day in allowed_days:
            return None
        if allowed_weekdays is not None and day.weekday() in allowed_weekdays:
            return None
    return None


def next_run(expression: str, after: datetime) -> datetime | None:
    try:
        fields = _split_expression(expression)
    except ValueError:
        raise ValueError("invalid expression")

    minute_field, hour_field, day_field, month_field, weekday_field = fields

    month_field_norm = month_field.strip()
    day_field_norm = day_field.strip()
    weekday_field_norm = weekday_field.strip()

    allowed_months = _parse_month_field(month_field_norm)
    allowed_days = _parse_day_field(day_field_norm)
    allowed_weekdays = _parse_weekday_field(weekday_field_norm)

    after = after.replace(second=0, microsecond=0)
    if not isinstance(after, datetime.datetime):
        raise TypeError("after must be datetime")
    if after.tzinfo is not None:
        after = after.replace(tzinfo=None)

    max_year = after.year + 10
    if max_year > 9999:
        max_year = 9999
    if max_year < after.year:
        return None

    # Check current day first; if after already at/after last minute, move to next day.
    start_day = after.date()
    if after == datetime.datetime.combine(start_day, datetime.time()):
        # Same-day times equal to after are invalid; if no later time, use next day.
        # Try to find any allowed time today.
        candidate = _next_run_after_date_on_day(start_day, allowed_months, allowed_days, allowed_weekdays)
        if candidate is not None:
            # If the only available time is same minute but after has seconds==0? handled by time selection below.
            pass

    return None
